import assert from "node:assert/strict";
import test from "node:test";

import {
  OaSessionError,
  verifyOaSession,
} from "../src/automation/auth/oaSession.js";
import { createSignedOaSession, signOaSessionPayload } from "./helpers/oaSessionFixture.js";

// Generated by Python:
// TimestampSigner("dummy").sign(base64.b64encode(b'{"user_id":42}'))
const PYTHON_SIGNED_SESSION =
  "eyJ1c2VyX2lkIjo0Mn0=.anrC2Q.pEFWxzjfMt0mY3AiF3rdGDgnmrk";

test("verifies an OA itsdangerous session and extracts user_id", () => {
  const session = verifyOaSession(PYTHON_SIGNED_SESSION, {
    secret: "dummy",
    maxAgeSeconds: 0,
    nowSeconds: 1_800_000_000,
  });

  assert.equal(session.userId, 42);
  assert.equal(session.payload.user_id, 42);
});

test("verifies a compressed OA session while preserving its signed compression marker", () => {
  const payload = { user_id: 42, permissions: "oa-permission,".repeat(200) };
  const token = createSignedOaSession(payload, true);
  const session = verifyOaSession(token, { secret: "dummy", maxAgeSeconds: 0 });

  assert.equal(session.userId, 42);
  assert.deepEqual(session.payload, payload);
  assert.equal(session.signedAtSeconds, 1_800_000_000);
});

test("rejects adding or removing the signed compression marker", () => {
  for (const token of [
    createSignedOaSession({ user_id: 42 }, true).slice(1),
    `.${PYTHON_SIGNED_SESSION}`,
  ]) {
    assert.throws(() => verifyOaSession(token, { secret: "dummy", maxAgeSeconds: 0 }), {
      code: "invalid_session",
    });
  }
});

test("rejects compressed payload corruption and tampered signatures", () => {
  const compressed = createSignedOaSession({ user_id: 42 }, true);
  for (const token of [
    `${compressed}x`,
    signOaSessionPayload(`.${Buffer.from("not zlib").toString("base64url")}`),
  ]) {
    assert.throws(() => verifyOaSession(token, { secret: "dummy", maxAgeSeconds: 0 }), {
      code: "invalid_session",
    });
  }
});

test("applies expiration checks to compressed sessions", () => {
  const token = createSignedOaSession({ user_id: 42 }, true, 1_800_000_000);
  assert.throws(() => verifyOaSession(token, {
    secret: "dummy", maxAgeSeconds: 60, nowSeconds: 1_800_000_061,
  }), { code: "expired_session" });
});

test("does not decode URI escapes in an already extracted session token", () => {
  assert.throws(() => verifyOaSession(encodeURIComponent(PYTHON_SIGNED_SESSION), {
    secret: "dummy", maxAgeSeconds: 0,
  }), { code: "invalid_session" });
});

test("rejects invalid compressed user payloads and excessive decompression", () => {
  for (const payload of [null, [], { user_id: 0 }, { user_id: "42" }, {
    user_id: 42, data: "a".repeat(1024 * 1024 + 1),
  }]) {
    assert.throws(() => verifyOaSession(createSignedOaSession(payload, true), {
      secret: "dummy", maxAgeSeconds: 0,
    }), { code: "invalid_session" });
  }
});

test("rejects a tampered OA session", () => {
  assert.throws(
    () =>
      verifyOaSession(`${PYTHON_SIGNED_SESSION}x`, {
        secret: "dummy",
        maxAgeSeconds: 0,
      }),
    (error: unknown) =>
      error instanceof OaSessionError && error.code === "invalid_session",
  );
});

test("enforces max age when OA_SESSION_VERIFY_MAX_AGE is positive", () => {
  assert.throws(
    () =>
      verifyOaSession(PYTHON_SIGNED_SESSION, {
        secret: "dummy",
        maxAgeSeconds: 60,
        nowSeconds: 1_800_000_000,
      }),
    (error: unknown) =>
      error instanceof OaSessionError && error.code === "expired_session",
  );
});

